style.css:
/* Soft Coquette ♡ */
body {
  background: #FFF5F7 !important;
  color: #684B55 !important;
}
h1, h2, h3 { color: #C47D96 !important; }
p { color: #806571 !important; }
a { color: #D68FA9 !important; }
button {
  background: #F4B6C7 !important;
  color: #573C48 !important;
  border: 1px solid #E9A1B5 !important;
  border-radius: 12px !important;
}
input, textarea {
  background: #FCE4EC !important;
  color: #684B55 !important;
  border: 1px solid #E9A1B5 !important;
}
::selection { background: #E9A1B5; color: white; }
